class Counter:
    def __init__(self, start):
        self.value = start
    def bump(self, amount):
        self.value += amount
        return self.value
    def reset(self):
        self.value = 0

output:
class Counter:
    def __init__(self, start: int) -> None:
        self.value: int = start
    def bump(self, amount: int) -> int:
        self.value += amount
        return self.value
    def reset(self) -> None:
        self.value = 0

What changed: __init__ annotated -> None, attributes declared on first assignment and every method got a return type, so a stray return value in reset() is caught.

instruction:
Refactor this code by annotating the generator function properly:

def paginate(rows, size):
    chunk = []
    for r in rows:
        chunk.append(r)
        if len(chunk) == size:
            yield chunk
            chunk = []
    if chunk:
        yield chunk

output:
from typing import Iterator, List, TypeVar

T = TypeVar('T')

def paginate(rows: Iterator[T], size: int) -> Iterator[List[T]]:
    chunk: List[T] = []
    for r in rows:
        chunk.append(r)
        if len(chunk) == size:
            yield chunk
            chunk = []
    if chunk:
        yield chunk

What changed: Iterator[List[T]] with a TypeVar keeps the element type generic while telling type checkers this is a lazy generator, not a list.

