from typing import Any, Dict

def render(template: str, *, escape: bool, compact: bool, **ctx: Any) -> str:
    out = template.format(**ctx)
    if escape:
        out = html_escape(out)
    if compact:
        out = ' '.join(out.split())
    return out

What changed: keyword-only flags typed as bool and the variadic context as **ctx: Any; the missing **ctx parameter also became visible in the signature.

