Refactor this code by annotating the module-level pipeline API:

def read(path):
    with open(path) as f:
        return [line.strip() for line in f]

def transform(lines):
    return [l for l in lines if l]

def write(path, lines):
    with open(path, 'w') as f:
        f.write('\n'.join(lines))

output:
from typing import List

def read(path: str) -> List[str]:
    with open(path) as f:
        return [line.strip() for line in f]

def transform(lines: List[str]) -> List[str]:
    return [l for l in lines if l]

def write(path: str, lines: List[str]) -> None:
    with open(path, 'w') as f:
        f.write('\n'.join(lines))

What changed: the str -> List[str] pipeline is now visible end to end; passing a single string to transform() fails a type check instead of iterating characters.

